class BagianBantuan {
  final String judul;
  final String isi;
  const BagianBantuan(this.judul, this.isi);
}

class ArtikelBantuan {
  final String id;
  final String judul;
  final String ringkasan;
  final List<BagianBantuan> bagian;
  final List<String> workflow;
  final List<String> ilustrasi;
  const ArtikelBantuan({
    required this.id,
    required this.judul,
    required this.ringkasan,
    required this.bagian,
    this.workflow = const [],
    this.ilustrasi = const [],
  });

  int get jumlahKata => bagian
      .map((b) => '${b.judul} ${b.isi}')
      .join(' ')
      .trim()
      .split(RegExp(r'\s+'))
      .where((kata) => kata.isNotEmpty)
      .length;
}

